scripts.host.probe:
{
  "schema": 1,
  "timeout_ms": 360000,
  "label_dump": {
    "every_ms": 5000
  },
  "steps": [
    {
      "op": "wait",
      "editing": true
    },
    {
      "op": "assert_relay"
    },
    {
      "op": "editor_pick",
      "input_player": 0
    },
    {
      "op": "editor_move",
      "input_player": 0,
      "x_fraction": 0.35
    },
    {
      "op": "wait",
      "renders": 5,
      "elapsed_ms": 1000
    },
    {
      "op": "menu",
      "command": "video_mark valid-preview-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "valid-preview-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "screen_text": "Valid spot - click to INSTALL your brain"
      }
    },
    {
      "op": "assert_net_ui_clear",
      "player": 0
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "0 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": true
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "game_mouse",
      "button": "left",
      "down": false
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "setup_ready": 1
    },
    {
      "op": "menu",
      "command": "video_mark placed-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "placed-host",
      "scope": "menu"
    },
    {
      "op": "assert_editor",
      "input_player": 0,
      "equals": {
        "ready": true,
        "submitted": true,
        "screen_text": "READY to start - wait for others to finish..."
      }
    },
    {
      "op": "assert_net_ui_clear",
      "player": 0
    },
    {
      "op": "assert_control",
      "control": "LabelNetMatchStatus",
      "text_contains": "1 of 2",
      "fits": true,
      "inside": "BoxNetMatchStatus"
    },
    {
      "op": "key_down",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Return"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "editing": false,
      "paused": false
    },
    {
      "op": "assert",
      "equals": {
        "setup_ready": 2,
        "setup_humans": 2,
        "local_actor_alive": true
      }
    },
    {
      "op": "assert_scene",
      "input_player": 0,
      "equals": {
        "alive": true,
        "brain_count": 2
      }
    },
    {
      "op": "menu",
      "command": "video_mark playing-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "playing-host",
      "scope": "menu"
    },
    {
      "op": "key_down",
      "key": "Escape"
    },
    {
      "op": "wait",
      "renders": 3,
      "sim_advanced": 2
    },
    {
      "op": "key_up",
      "key": "Escape"
    },
    {
      "op": "wait",
      "renders": 3
    },
    {
      "op": "wait",
      "screen": "Pause"
    },
    {
      "op": "menu",
      "command": "activate ButtonEndMatch"
    },
    {
      "op": "wait",
      "screen": "PauseLeaveConfirm"
    },
    {
      "op": "menu",
      "command": "activate ButtonLeaveConfirm"
    },
    {
      "op": "wait",
      "scope": "menu",
      "screen": "MultiplayerScreen",
      "control": "LabelMultiplayerStatus",
      "text_contains": "Waiting for Joiner to press Ready"
    },
    {
      "op": "menu",
      "command": "video_mark rematch-waiting-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "rematch-waiting-host",
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "text_watch start rematch-state equals substate:Lobby LabelMultiplayerStatus Waiting for Joiner to press Ready"
    },
    {
      "op": "menu",
      "command": "text_watch start rematch-duplicates duplicates substate:Lobby"
    },
    {
      "op": "menu",
      "command": "text_watch start rematch-layout layout substate:Lobby"
    },
    {
      "op": "wait",
      "elapsed_ms": 4000,
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "text_watch assert rematch-state"
    },
    {
      "op": "menu",
      "command": "text_watch assert rematch-duplicates"
    },
    {
      "op": "menu",
      "command": "text_watch assert rematch-layout"
    },
    {
      "op": "menu",
      "command": "activate ButtonMultiplayerStart"
    },
    {
      "op": "wait",
      "scope": "menu",
      "control": "LabelMultiplayerStatus",
      "text_contains": "Starting in 30 s"
    },
    {
      "op": "menu",
      "command": "video_mark rematch-countdown-host"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "rematch-countdown-host",
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "assert_label ButtonMultiplayerStart Cancel Start"
    },
    {
      "op": "wait",
      "elapsed_ms": 2200,
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "activate ButtonMultiplayerStart"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "assert_label LabelMultiplayerStatus Waiting for Joiner to press Ready"
    },
    {
      "op": "signal",
      "name": "done",
      "scope": "menu"
    },
    {
      "op": "finish"
    }
  ],
  "activate_phase": "Running",
  "sim_clock": "lockstep"
}

